// TypeMappingService.java — maps Oracle types to PostgreSQL equivalents
package com.nbi.db;

import java.util.Map;

public class TypeMappingService {
    // The canonical Oracle -> PostgreSQL type mapping used in migration.
    private static final Map<OracleType, String> MAP = Map.of(
        OracleType.VARCHAR2, "VARCHAR / TEXT",
        OracleType.CLOB,     "TEXT",       // <-- the key answer
        OracleType.NCLOB,    "TEXT",
        OracleType.BLOB,     "BYTEA",
        OracleType.NUMBER,   "NUMERIC",
        OracleType.DATE,     "TIMESTAMP"
    );

    public String toPostgres(OracleType t) {
        return MAP.getOrDefault(t, "TEXT");
    }
}
