// Complaint.java — a complaint whose narrative can be arbitrarily long
package com.nbi.db;

public class Complaint {
    private final long id;
    private final String customerName; // short VARCHAR-style
    private final String narrative;    // long TEXT-style (was Oracle CLOB)

    public Complaint(long id, String customerName, String narrative) {
        this.id = id;
        this.customerName = customerName;
        this.narrative = narrative;
    }
    public long getId() { return id; }
    public String getCustomerName() { return customerName; }
    public String getNarrative() { return narrative; }
}
