// ComplaintRepository.java — simulates a TEXT column round-trip (no locator)
package com.nbi.db;

import java.util.HashMap;
import java.util.Map;

public class ComplaintRepository {
    private final Map<Long, Complaint> table = new HashMap<>();

    // In real PostgreSQL this is a plain INSERT — no DBMS_LOB, no streaming.
    public void save(Complaint c) {
        table.put(c.getId(), c);
    }

    // A plain SELECT returns the whole TEXT value directly as a String.
    public Complaint findById(long id) {
        return table.get(id);
    }
}
