// Demo.java — proves CLOB-sized text behaves like a normal TEXT column
package com.nbi.db;

public class Demo {
    public static void main(String[] args) {
        TypeMappingService mapper = new TypeMappingService();
        System.out.println("Oracle CLOB  -> PostgreSQL " + mapper.toPostgres(OracleType.CLOB));
        System.out.println("Oracle BLOB  -> PostgreSQL " + mapper.toPostgres(OracleType.BLOB));

        // Build a long narrative (~5000 chars) that in Oracle required a CLOB.
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 100; i++) {
            sb.append("The customer reports an unauthorized debit on their account and ");
        }
        String longNarrative = sb.toString();

        ComplaintRepository repo = new ComplaintRepository();
        repo.save(new Complaint(1L, "Rajesh Kumar", longNarrative));

        Complaint loaded = repo.findById(1L);
        System.out.println("Stored narrative length = " + loaded.getNarrative().length() + " chars");
        boolean intact = loaded.getNarrative().equals(longNarrative);
        System.out.println("Round-trip intact (no locator needed) = " + intact);
    }
}
